import map from '@/research-map.json';

interface Area {
  id: string;
  title: string;
  blurb: string;
  systems: { slug: string; name: string; href: string }[];
  skillCount: number;
}

/**
 * Research-area mini-map: a declared taxonomy (generated by
 * scripts/gen_research_map.py, run under monitor-website) that lets a visitor
 * see the shape of the program before decoding ten codenames. Text and rules
 * only — no animated graph.
 */
export function ResearchMap() {
  // Homepage shows the areas with a flagship project (a scan layer for the
  // collage below). The full eight-area taxonomy (incl. skills-only areas like
  // ML, design, media) lives in research-map.json for the /explore/ search.
  const areas = (map.areas as Area[]).filter((a) => a.systems.length > 0);
  return (
    <div className="research-map" aria-label="Research areas">
      {areas.map((a) => (
        <section className="rm-area" key={a.id}>
          <h3 className="rm-title">
            {a.title}
            <span className="rm-count">
              {a.skillCount} {a.skillCount === 1 ? 'skill' : 'skills'}
            </span>
          </h3>
          <p className="rm-blurb">{a.blurb}</p>
          <p className="rm-systems">
            {a.systems.map((s, i) => (
              <span key={s.slug}>
                {i > 0 && <span aria-hidden="true"> · </span>}
                <a
                  href={`#project-${s.slug}`}
                  data-qid={`researchmap:jump:${s.slug}`}
                  data-qs-action="RESEARCHMAP_JUMP_PROJECT"
                  title={`Jump to ${s.name} below`}
                >
                  {s.name}
                </a>
              </span>
            ))}
          </p>
        </section>
      ))}
    </div>
  );
}
